import { AnythingLauncherModule } from '@anythingai/launcher'
import { useCallback, useEffect, useReducer } from 'react'
import { getRoutesByProjectGroupId } from '../getRoutesByProjectGroupId'
import { pathChangeEmitter, PathChangeEvents } from '@/utils'

export type LauncherState =
	| {
			isLoading: true
			mode: null
			initialWebPath: null
	  }
	| {
			isLoading: false
			mode: 'web' | 'mobile'
			initialWebPath: string | null
	  }

type Action =
	| {
			type: 'INITIALIZE'
			payload: {
				mode: 'web' | 'mobile'
				initialWebPath: string | null
			}
	  }
	| { type: 'SWITCH_MODE'; payload: { mode: 'web' | 'mobile' } }

const initialState: LauncherState = {
	isLoading: true,
	mode: null,
	initialWebPath: null
}

function reducer(state: LauncherState, action: Action): LauncherState {
	switch (action.type) {
		case 'INITIALIZE':
			return { ...state, ...action.payload, isLoading: false }
		case 'SWITCH_MODE':
			pathChangeEmitter.emit(PathChangeEvents.PATH_CHANGE, {
				path: ''
			})
			if (state.mode === action.payload.mode || state.isLoading) {
				return state
			}
			return { ...state, mode: action.payload.mode }
		default:
			return state
	}
}

export function useLauncherState() {
	const [state, dispatch] = useReducer(reducer, initialState)
	useEffect(() => {
		if (!AnythingLauncherModule) {
			throw new Error('AnythingLauncher is not available')
		}

		const projectGroupId = process.env.EXPO_PUBLIC_PROJECT_GROUP_ID

		if (state.isLoading) {
			Promise.all([
				AnythingLauncherModule.isWeb(),
				projectGroupId
					? getRoutesByProjectGroupId({ projectGroupId })
					: Promise.resolve(null)
			]).then(([isWeb, routes]) => {
				let initialWebPath = null
				let mode: 'web' | 'mobile' = isWeb ? 'web' : 'mobile'
				if (routes) {
					const hasReactRoute = routes.some(
						(route) => route.runtime === 'REACT'
					)
					const hasExpoRoute = routes.some((route) => route.runtime === 'EXPO')
					if (mode === 'web' && !hasReactRoute && hasExpoRoute) {
						mode = 'mobile'
					}
					if (mode === 'mobile' && hasReactRoute && !hasExpoRoute) {
						mode = 'web'
					}

					const shortestRoute = routes.reduce(
						(shortest, current) =>
							current.runtime === 'REACT' &&
							(shortest.path === '' ||
								current.path.length < shortest.path.length)
								? current
								: shortest,
						{ path: '', runtime: 'REACT' }
					)
					if (shortestRoute.path !== '') {
						initialWebPath = shortestRoute.path
					}
				}

				dispatch({
					type: 'INITIALIZE',
					payload: {
						mode,
						initialWebPath
					}
				})
			})
		}
	}, [state.isLoading])

	const switchToWeb = useCallback(() => {
		dispatch({ type: 'SWITCH_MODE', payload: { mode: 'web' } })
	}, [])

	const switchToMobile = useCallback(() => {
		dispatch({ type: 'SWITCH_MODE', payload: { mode: 'mobile' } })
	}, [])

	return { state, switchToWeb, switchToMobile }
}
